import{_ as e,o as r,c as t,a3 as i}from"./chunks/framework.BTt0kA_k.js";const u=JSON.parse('{"title":"操作记录","description":"","frontmatter":{},"headers":[],"relativePath":"user/use/operations.md","filePath":"user/use/operations.md"}'),o={name:"user/use/operations.md"};function l(s,a,n,p,d,h){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="操作记录" tabindex="-1">操作记录 <a class="header-anchor" href="#操作记录" aria-label="Permalink to &quot;操作记录&quot;">​</a></h1><p>入口：<strong>运行 → 操作记录</strong>。操作记录用于了解“谁在什么时候执行了什么，以及是否完成”。单次模型请求的技术细节在<a href="./records.html">探测记录</a>中查看。</p><h2 id="筛选操作" tabindex="-1">筛选操作 <a class="header-anchor" href="#筛选操作" aria-label="Permalink to &quot;筛选操作&quot;">​</a></h2><p>可以按以下条件组合查找：</p><ul><li>时间范围：选择开始、结束日期，或使用最近一周、最近 15 天、最近 30 天等快捷范围。</li><li>操作来源：系统或用户。</li><li>执行结果：成功、失败、已取消、受阻。</li><li>操作动作：按页面提供的动作分类筛选。</li></ul><p>筛选支持多选。表格展示来源、动作、操作概要、结果和时间，支持分页。</p><h2 id="阅读详情" tabindex="-1">阅读详情 <a class="header-anchor" href="#阅读详情" aria-label="Permalink to &quot;阅读详情&quot;">​</a></h2><p>打开某一行的详情，可以看到时间、来源、执行者、操作对象，以及这次事件保存的内容。</p><p>配置变更可能展示修改前后值；创建或删除事件可能展示当时的快照；运行类事件可能展示执行过程或关联记录入口。详情里的名称和值反映事件发生时的内容。</p><p>敏感字段以“已配置”“已更换”“已隐藏”等形式展示，不会直接显示 API Key。</p><h2 id="从操作记录追踪失败" tabindex="-1">从操作记录追踪失败 <a class="header-anchor" href="#从操作记录追踪失败" aria-label="Permalink to &quot;从操作记录追踪失败&quot;">​</a></h2><ol><li>按问题发生时间缩小范围。</li><li>选择“失败”或“受阻”，检查动作和操作对象。</li><li>打开详情，阅读失败原因和执行结果。</li><li>若有“关联探测记录”入口，继续查看对应的正式请求。</li></ol><p>“受阻”表示该操作未能按要求继续，例如当前站点已被其他任务占用；“已取消”表示流程被取消。它们都不能直接等同于模型服务故障。</p><p>某次操作没有生成正式探测记录时，详情会说明没有对应记录。配置草稿试探、页面操作和设置变更都可能出现这种情况。</p>',14)])])}const _=e(o,[["render",l]]);export{u as __pageData,_ as default};
